window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-43601\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 338 na letra χ · nº geral 43601</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer um tecido de malha; entrelaçar; tecer ♦ pas. 2 ter os pés, ac., amarrados como em um tecido. 〈χηλή〉</p></section></article>\n<article id=\"entry-dgp-43602\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηλή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 339 na letra χ · nº geral 43602</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 casco de cavalo, de boi, de cabra 2 pata de lobo 3 pl. garras das aves 4 pinça do caranguejo 5 pinça; tenaz 6 quebramar 7 braço de um dique 8 curva de uma margem ♦ Χηλαί 9 Escorpião, constelação.</p></section></article>\n<article id=\"entry-dgp-43603\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηλός, οῦ (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 340 na letra χ · nº geral 43603</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">baú; arca; cofre.</p></section></article>\n<article id=\"entry-dgp-43604\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χἠμεῖς</h1><div class=\"entry-meta\"><span>DGP · ordem 341 na letra χ · nº geral 43604</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de χαὶ ἡμεῖς.</p></section></article>\n<article id=\"entry-dgp-43605\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χἠμέρα</h1><div class=\"entry-meta\"><span>DGP · ordem 342 na letra χ · nº geral 43605</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de καὶ ἡμέρα.</p></section></article>\n<article id=\"entry-dgp-43606\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χήμη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 343 na letra χ · nº geral 43606</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de caramujo.</p></section></article>\n<article id=\"entry-dgp-43607\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χήν, χηνός</h1><div class=\"entry-meta\"><span>DGP · ordem 344 na letra χ · nº geral 43607</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. pl. χένας (ὁ, ἡ) ganso.</p></section></article>\n<article id=\"entry-dgp-43608\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηναλωπεκιδεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 345 na letra χ · nº geral 43608</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filhotes de ganso do Egito. 〈χηναλώπηξ〉</p></section></article>\n<article id=\"entry-dgp-43609\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηναλώπηξ, εκος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 346 na letra χ · nº geral 43609</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ganso do Egito. 〈χήν, ἀλώπηξ〉</p></section></article>\n<article id=\"entry-dgp-43610\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χήνειος,</h1><div class=\"entry-meta\"><span>DGP · ordem 347 na letra χ · nº geral 43610</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. χήνεος, η, ον de ganso. 〈χήν〉</p></section></article>\n<article id=\"entry-dgp-43611\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηνιδεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 348 na letra χ · nº geral 43611</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filhote de ganso. 〈χήν〉</p></section></article>\n<article id=\"entry-dgp-43612\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηνίσκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 349 na letra χ · nº geral 43612</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequeno ganso 2 popa de navio recurvada como o pescoço de um ganso. 〈χήν〉</p></section></article>\n<article id=\"entry-dgp-43613\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χήρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 350 na letra χ · nº geral 43613</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de χῆρος.</p></section></article>\n<article id=\"entry-dgp-43614\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηραμός, οῦ (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 351 na letra χ · nº geral 43614</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 buraco; cavidade; oco 2 toca; covil.</p></section></article>\n<article id=\"entry-dgp-43615\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χήρατο</h1><div class=\"entry-meta\"><span>DGP · ordem 352 na letra χ · nº geral 43615</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. ou pl. aor. méd. poét. de χαίρω.</p></section></article>\n<article id=\"entry-dgp-43616\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηρεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 353 na letra χ · nº geral 43616</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 viuvez 2 privação; falta de, gen. 〈χηρεύω〉</p></section></article>\n<article id=\"entry-dgp-43617\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηρεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 354 na letra χ · nº geral 43617</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ficar viúvo ou viúva; enviuvar; ficar só 2 estar vazio; estar privado de, gen. 〈χῆρος〉</p></section></article>\n<article id=\"entry-dgp-43618\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χήρη</h1><div class=\"entry-meta\"><span>DGP · ordem 355 na letra χ · nº geral 43618</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. jôn. de χῆρος.</p></section></article>\n<article id=\"entry-dgp-43619\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χῆρος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 356 na letra χ · nº geral 43619</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 privado de parente 2 privado de cônjuge; viúvo ou viúva 3 desprovido; vazio; privado; despojado de, gen.</p></section></article>\n<article id=\"entry-dgp-43620\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 357 na letra χ · nº geral 43620</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. χηρώσω, aor. ἐχήρωσα, poét. 3ª sing χήρωσε, aor. méd. 3ª pl. ἐχηρώσαντο; pas. fut. χηρώσομαι, aor. ἐχηρώθην) at. e méd. 1 tornar vazio; tornar deserto 2 privar alguém, ac., de algo, gen. 3 tornar alguém, ac., viúvo ou viúva 4 tornar-se privado de, gen. 5 viver na viuvez ♦ pas. 6 ser privado de, gen. 7 ser solitário.</p></section></article>\n<article id=\"entry-dgp-43621\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηρωσταί, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 358 na letra χ · nº geral 43621</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">parentes distantes (herdeiros na falta de um herdeiro direto).</p></section></article>\n<article id=\"entry-dgp-43622\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χἠσεῖτε</h1><div class=\"entry-meta\"><span>DGP · ordem 359 na letra χ · nº geral 43622</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase dór. de καὶ ἥσετε, 2ª pl. fut. de ἵημι.</p></section></article>\n<article id=\"entry-dgp-43623\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χῆτος</h1><div class=\"entry-meta\"><span>DGP · ordem 360 na letra χ · nº geral 43623</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só dat. sing. χήτεϊ (τό) falta; ausência de, gen.</p></section></article>\n<article id=\"entry-dgp-43624\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χἤφθα</h1><div class=\"entry-meta\"><span>DGP · ordem 361 na letra χ · nº geral 43624</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase dór. de καὶ ἥφθα.</p></section></article>\n<article id=\"entry-dgp-43625\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθαμαλοπτήτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 362 na letra χ · nº geral 43625</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que voa baixo; de voo rasante. 〈χθαμαλός, πέτομαι〉</p></section></article>\n<article id=\"entry-dgp-43626\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθαμαλός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 363 na letra χ · nº geral 43626</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que está no nível da terra; que está na terra; baixo 2 baixo; vil ♦ τὰ χθαμαλά 3 regiões baixas. 〈χαμαί〉</p></section></article>\n<article id=\"entry-dgp-43627\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθές</h1><div class=\"entry-meta\"><span>DGP · ordem 364 na letra χ · nº geral 43627</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. ontem.</p></section></article>\n<article id=\"entry-dgp-43628\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθεσινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 365 na letra χ · nº geral 43628</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">χθιζός.</p></section></article>\n<article id=\"entry-dgp-43629\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθιζά</h1><div class=\"entry-meta\"><span>DGP · ordem 366 na letra χ · nº geral 43629</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">χθιζός.</p></section></article>\n<article id=\"entry-dgp-43630\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθιζινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 367 na letra χ · nº geral 43630</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">χθιζός.</p></section></article>\n<article id=\"entry-dgp-43631\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθιζός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 368 na letra χ · nº geral 43631</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de ontem: χθιζὸς ἔβη hom. veio ontem, ὅσσα χθιζὸς ὑπέσχετο hom. tudo o que prometeste ontem ♦ τὸ χθιζόν adv. 2 ontem. 〈χθές〉</p></section></article>\n<article id=\"entry-dgp-43632\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθόνιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 369 na letra χ · nº geral 43632</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 do fundo da terra; ctônio; subterrâneo: χθονία πορεία plat. caminho subterrâneo, ἠχὼ χθόνιος eur. barulho subterrâneo 2 que habita ou adentra os infernos; ctônio: αἱ χθονίαι θεαί as deuses infernais, Deméter e Perséfone ou as Erínias, χθόνιος Ἑρμῆς Hermes ctônio, que conduz os mortos para baixo da terra 3 que se mantém sob a terra: χθόνιον στόμα pínd. a entrada subterrânea do Hades 4 provindo da terra: χθόνιοι Τιτῆνες hes. os Titãs terrígenos, βροντήμασι χθονίοις ésql. com trovões vindos do fundo da terra 5 que se faz sobre a terra; terrestre 6 do país; da região: χθόνιοι θεοί eur. deuses do país, χθόνιαι ἡρῷσσαι a.r. heroínas da região ♦ ὁ χθόνιος 7 divindade ctônia: μᾶνιν χθονίων a cólera dos deuses infernais ♦ ἡ χθονία 8 a deusa dos infernos, Deméter ou Hécate. 〈χθών〉</p></section></article>\n<article id=\"entry-dgp-43633\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθονοστιβής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 370 na letra χ · nº geral 43633</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que anda sobre a terra; terreno; terrestre. 〈χθών, στείβω〉</p></section></article>\n<article id=\"entry-dgp-43634\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθονοτρεφής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 371 na letra χ · nº geral 43634</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alimentado pela terra; nascido da terra. 〈χθών, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-43635\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χθών, χθονός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 372 na letra χ · nº geral 43635</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 superfície da terra; terra; solo; chão: ἐπὶ χθονὶ χεῖτο τανυσθείς hom. jazia estendido no chão, ἄριστον ἄνδρα τῶν ἐπὶ χθονί sóf. o melhor dos homens que vivem sobre a terra, ἐτέθαπτο ὑπὸ χθονός hom. estava enterrado sob a terra, ὦ κατὰ χθονός θεαί ésql. divindades subterrâneas 2 a terra no seu conjunto; a terra inteira: ἐπ᾽ ἔσχατα χθονός sóf. nas extremidades da terra 3 terra; região; país: χθὼν Ἀσιῆτις ésql. a terra da Ásia, χθὼν Λήμνου sóf. a terra de Lemnos, πᾶσαν τὴν Μυκηναίων χθόνα sóf. todo o país dos micênios, τῆσδε δημοῦχοι χθονός sóf. habitantes desse país ♦ Χθών 4 a Terra, person.</p></section></article>\n<article id=\"entry-dgp-43636\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χῖ (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 373 na letra χ · nº geral 43636</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. a letra Χ (khi).</p></section></article>\n<article id=\"entry-dgp-43637\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιαρχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 374 na letra χ · nº geral 43637</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐχιλιάρχουν, aor. ἐκιλιάρχησα, part. perf. κεχιλιαρχηκώς) 1 Mil. ser quiliarco; comandar uma quiliarquia 2 em Roma, ser tribuno militar. 〈χι­λίαρχος〉</p></section></article>\n<article id=\"entry-dgp-43638\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιάρχης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 375 na letra χ · nº geral 43638</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = χιλίαρχος.</p></section></article>\n<article id=\"entry-dgp-43639\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιαρχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 376 na letra χ · nº geral 43639</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Mil. função de quiliarco; quiliarquia 2 Mil. formação de 1024 soldados; quiliarquia 3 em Roma, função de tribuno militar 4 bíbl., milhar, em Israel. 〈χιλίαρχος〉</p></section></article>\n<article id=\"entry-dgp-43640\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλίαρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 377 na letra χ · nº geral 43640</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 comandante de uma guarnição de mil homens; quiliarco 2 em Roma, tribuno militar 3 na Pérsia e na Macedônia, quiliarco, o mais alto cargo abaixo do rei. 〈χίλιοι, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-43641\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 378 na letra χ · nº geral 43641</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mil; milhar 2 grande número 3 bíbl. milênio. 〈χίλιοι〉</p></section></article>\n<article id=\"entry-dgp-43642\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιέτης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 379 na letra χ · nº geral 43642</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e χιλιετής, ής, ές de mil anos. 〈χίλιοι, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-43643\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χίλιοι, αι, α</h1><div class=\"entry-meta\"><span>DGP · ordem 380 na letra χ · nº geral 43643</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">num. card. 1 mil: χίλιοι Πελοποννησίων tuc. mil peloponésios, πεντακόσιοι καὶ χιλιοι xen. ou χίλιοι καὶ πεντακόσιοι ésqn. mil e quinhentos, χίλιοι ἐπὶ μυρίοις plat. mil e mais dez mil, i.e., onze mil, τέτταρας πρὸς τοῖς χιλίοις luc. quatro e mais mil, i.e., mil e quatro ♦ χίλιαι 2 mil dracmas: περὶ χιλίων κινδυνεύειν dem. arriscar-se a uma multa de mil dracmas.</p></section></article>\n<article id=\"entry-dgp-43644\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιόναυς, εως</h1><div class=\"entry-meta\"><span>DGP · ordem 381 na letra χ · nº geral 43644</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. χιλιόναυσι (masc., fem.) de mil navios (frota).</p></section></article>\n<article id=\"entry-dgp-43645\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιοναύτας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 382 na letra χ · nº geral 43645</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) dór. 1 de mil marinheiros (expedição) 2 de mil navios (frota). 〈χίλιοι, ναύτης〉</p></section></article>\n<article id=\"entry-dgp-43646\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιοστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 383 na letra χ · nº geral 43646</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">num. ord. 1 milésimo ♦ ἡ χιλιοστή 2 taxa, tributo de um milésimo.</p></section></article>\n<article id=\"entry-dgp-43647\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιοστύς, ύος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 384 na letra χ · nº geral 43647</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tropa de mil homens: χ. τῶν ἱππέων xen. corpo de mil cavaleiros.</p></section></article>\n<article id=\"entry-dgp-43648\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλιοτάλαντος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 385 na letra χ · nº geral 43648</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que pesa ou que vale mil talentos. 〈χίλιοι, τάλαντον〉</p></section></article>\n<article id=\"entry-dgp-43649\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 386 na letra χ · nº geral 43649</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 forragem; pastagem 2 mantimento.</p></section></article>\n<article id=\"entry-dgp-43650\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 387 na letra χ · nº geral 43650</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐχίλου) levar ao pasto; forragear.</p></section></article>\n<article id=\"entry-dgp-43651\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χίμαιρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 388 na letra χ · nº geral 43651</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cabra 2 cabra jovem; cabrita, partic. cabrita imolada em honra de Ártemis, antes dos combates ♦ Χίμαιρα 3 Quimera, monstro com cabeça de leão, corpo de cabra e cauda de serpente.</p></section></article>\n<article id=\"entry-dgp-43652\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χίμαρος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 389 na letra χ · nº geral 43652</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cabrito; cabrita.</p></section></article>\n<article id=\"entry-dgp-43653\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χίμεθλον</h1><div class=\"entry-meta\"><span>DGP · ordem 390 na letra χ · nº geral 43653</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e χίμετλον, ου (τό) frieira.</p></section></article>\n<article id=\"entry-dgp-43654\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιονίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 391 na letra χ · nº geral 43654</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐχιόνιζον; part. perf. pas. κεχιονισμένος) cair neve; nevar em, ac.</p></section></article>\n<article id=\"entry-dgp-43655\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιονόβλητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 392 na letra χ · nº geral 43655</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recoberto de neve; congelado pela neve. 〈χιών, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-43656\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιονοβόλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 393 na letra χ · nº geral 43656</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que traz a neve. 〈χιών, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-43657\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιονόκτυπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 394 na letra χ · nº geral 43657</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">batido pela neve; resfriado pela neve (monte). 〈χιών, κτυπέω〉</p></section></article>\n<article id=\"entry-dgp-43658\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιονώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 395 na letra χ · nº geral 43658</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 branco como a neve; níveo 2 coberto de neve. 〈χιών, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-43659\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Χίος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 396 na letra χ · nº geral 43659</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Quios, cidade e ilha do mar Egeu.</p></section></article>\n<article id=\"entry-dgp-43660\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Χῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 397 na letra χ · nº geral 43660</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Quios: Χῖος ἀοιδός hom. aedo de Quios, Homero, Χῖος οἶνος ar. vinho de Quios ♦ ὁ Χῖος 2 vinho de Quios 3 golpe de Quios, num jogo em que se brinca com os ossos tirados da pata do carneiro 4 pl. habitantes de Quios ♦ ἡ Χία 5 navio de Quios.</p></section></article>\n<article id=\"entry-dgp-43661\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιτών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 398 na letra χ · nº geral 43661</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 túnica masculina, vestuário de baixo, sem mangas, colocado diretamente sobre a pele 2 túnica feminina, de linho, longa e com mangas 3 vestuário de luta; cota; armadura 4 envoltório de pedras; muralha 5 qualquer coisa que recobre; revestimento 6 Bot. película de sementes, frutos e bulbos 7 casca de árvore; cortiça 8 rede de pesca 9 teia de aranha 10 Anat. membrana (do cérebro, dos intestinos) 11 em Roma, bandeira de cor chamativa, plantada diante da barraca do general, para dar sinal de marcha ou de combate.</p></section></article>\n<article id=\"entry-dgp-43662\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιτώνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 399 na letra χ · nº geral 43662</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequena túnica feminina.</p></section></article>\n<article id=\"entry-dgp-43663\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιτωνίσκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 400 na letra χ · nº geral 43663</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">túnica curta masculina.</p></section></article>\n<article id=\"entry-dgp-43664\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χιών, όνος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 401 na letra χ · nº geral 43664</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 neve 2 neve derretida; água gelada; água fresca.</p></section></article>\n<article id=\"entry-dgp-43665\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλαῖνα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 402 na letra χ · nº geral 43665</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 manto de inverno; sobretudo 2 capa.</p></section></article>\n<article id=\"entry-dgp-43666\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλαμύδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 403 na letra χ · nº geral 43666</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequena clâmide; pequeno manto.</p></section></article>\n<article id=\"entry-dgp-43667\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλαμυδουργία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 404 na letra χ · nº geral 43667</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">confecção de clâmide. 〈χλαμύς, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-43668\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλαμύς, ύδος</h1><div class=\"entry-meta\"><span>DGP · ordem 405 na letra χ · nº geral 43668</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(ἡ) 1 clâmide, capa de cavaleiro; manto curto 2 clâmide, capa usada pelos efebos: ἐκ χλαμύδος plut. ao desvestir a clâmide, i.e., ao deixar a categoria de efebo 3 capa de soldado 4 capa de comandante, de rei, de nobre, de general 5 roupa da cidade, op. à roupa do campo.</p></section></article>\n<article id=\"entry-dgp-43669\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλανίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 406 na letra χ · nº geral 43669</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequeno manto; capa feminina.</p></section></article>\n<article id=\"entry-dgp-43670\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλανιδοποιΐα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 407 na letra χ · nº geral 43670</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">confecção de manto leve. 〈χλανίς, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-43671\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλανίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 408 na letra χ · nº geral 43671</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 manto leve; capa 2 lençol; coberta.</p></section></article>\n<article id=\"entry-dgp-43672\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλευάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 409 na letra χ · nº geral 43672</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 chacotear; zombetear 2 escarnecer de; zombar de; ridicularizar, ac. ♦ méd. 3 rir; gracejar ♦ pas. 4 ser alvo de chacota. 〈χλεύη〉</p></section></article>\n<article id=\"entry-dgp-43673\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλευασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 410 na letra χ · nº geral 43673</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 zombaria; troça 2 ironia 3 gracejo. 〈χλευάζω〉</p></section></article>\n<article id=\"entry-dgp-43674\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλεύη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 411 na letra χ · nº geral 43674</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 zombaria; escárnio; riso; ridículo 2 alvo de escárnio; alvo de zombaria 3 ilusão; engano.</p></section></article>\n<article id=\"entry-dgp-43675\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλιαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 412 na letra χ · nº geral 43675</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. χλιανῶ, aor. ἐχλίανα e ἐχλίηνα, inf. χλιῆναι; pas. aor. ἐχλιάνθην, perf. κεχλίασμαι) 1 aquecer; reaquecer; reaquecer lentamente ♦ pas. 2 tornar-se quente; esquentar; aquecer-se 3 tornar-se febril; arder de paixão.</p></section></article>\n<article id=\"entry-dgp-43676\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλιαρός, ά,</h1><div class=\"entry-meta\"><span>DGP · ordem 413 na letra χ · nº geral 43676</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">όν 1 quente; levemente aquecido; tépido; morno ♦ τὸ χλιαρόν 2 tepidez; calor. 〈χλίω〉</p></section></article>\n<article id=\"entry-dgp-43677\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλιδανός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 414 na letra χ · nº geral 43677</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 refinado; delicado 2 efeminado.</p></section></article>\n<article id=\"entry-dgp-43678\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλιδάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 415 na letra χ · nº geral 43678</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser refinado, viçoso, exuberante 2 viver na moleza, na preguiça 3 orgulhar-se de; ficar envaidecido de; comprazer-se de, dat. 4 mostrar-se insolente.</p></section></article>\n<article id=\"entry-dgp-43679\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλιδή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 416 na letra χ · nº geral 43679</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 moleza; delicadeza 2 refinamento; luxo 3 insolência; soberba 4 ornamento luxuoso 5 beleza; fascínio.</p></section></article>\n<article id=\"entry-dgp-43680\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλίδημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 417 na letra χ · nº geral 43680</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 moleza; delicadeza; boa vida; luxo 2 orgulho; insolência 3 adorno luxuoso; belo adereço.</p></section></article>\n<article id=\"entry-dgp-43681\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλιδών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 418 na letra χ · nº geral 43681</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 adereço; enfeite 2 bracelete 3 adorno de tornozelo 4 colar.</p></section></article>\n<article id=\"entry-dgp-43682\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλίδωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 419 na letra χ · nº geral 43682</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ornamentação. 〈χλιδάω〉</p></section></article>\n<article id=\"entry-dgp-43683\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλίω</h1><div class=\"entry-meta\"><span>DGP · ordem 420 na letra χ · nº geral 43683</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">orgulhar-se; regozijar-se; comprazer-se.</p></section></article>\n<article id=\"entry-dgp-43684\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλόα</h1><div class=\"entry-meta\"><span>DGP · ordem 421 na letra χ · nº geral 43684</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = χλόη.</p></section></article>\n<article id=\"entry-dgp-43685\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλοάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 422 na letra χ · nº geral 43685</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar-se verde; enverdecer 2 ser verde 3 (planta) verdejar; brotar; germinar ♦ méd. 4 nutrir-se de ervas verdes.</p></section></article>\n<article id=\"entry-dgp-43686\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλοαυγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 423 na letra χ · nº geral 43686</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem um brilho esverdeado. 〈χλόα, αὐγή〉</p></section></article>\n<article id=\"entry-dgp-43687\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλοερός, ά,</h1><div class=\"entry-meta\"><span>DGP · ordem 424 na letra χ · nº geral 43687</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">όν 1 verde; verdejante 2 fresco; florescente.</p></section></article>\n<article id=\"entry-dgp-43688\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλόη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 425 na letra χ · nº geral 43688</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 erva ou grama ainda verde, nova 2 germe; rebento; broto 3 folhagem; fronde 4 verdura; erva ♦ Χλόη 5 Cloé, a verdejante, epít. da deusa Deméter 3 Cloé, n. de m.</p></section></article>\n<article id=\"entry-dgp-43689\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλοητόκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 426 na letra χ · nº geral 43689</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que produz brotos novos, verdejantes.</p></section></article>\n<article id=\"entry-dgp-43690\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλούνης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 427 na letra χ · nº geral 43690</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 selvagem (porco) ♦ ὁ χλούνης 2 porco do mato; javali 3 eunuco.</p></section></article>\n<article id=\"entry-dgp-43691\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλοῦνις (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 428 na letra χ · nº geral 43691</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">virilidade incipiente; puberdade.</p></section></article>\n<article id=\"entry-dgp-43692\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλωρεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 429 na letra χ · nº geral 43692</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pássaro de cor amarelada.</p></section></article>\n<article id=\"entry-dgp-43693\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλωρηΐς, ΐδος</h1><div class=\"entry-meta\"><span>DGP · ordem 430 na letra χ · nº geral 43693</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) fem. poét. de χλωρός.</p></section></article>\n<article id=\"entry-dgp-43694\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλωρίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 431 na letra χ · nº geral 43694</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fêmea do verdilhão (pássaro) 2 clóris, erva.</p></section></article>\n<article id=\"entry-dgp-43695\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλωρίων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 432 na letra χ · nº geral 43695</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">verdilhão amarelo (pássaro).</p></section></article>\n<article id=\"entry-dgp-43696\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλωρόκομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 433 na letra χ · nº geral 43696</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cabeleira verdejante; de folhas verdes.</p></section></article>\n<article id=\"entry-dgp-43697\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλωρόπτιλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 434 na letra χ · nº geral 43697</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de plumagem esverdeada.</p></section></article>\n<article id=\"entry-dgp-43698\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλωρός, ά,</h1><div class=\"entry-meta\"><span>DGP · ordem 435 na letra χ · nº geral 43698</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">όν 1 verde; coberto de vegetação; verdejante: χλωρὰς ῥῶπας hom. ramos verdes, ὄρος ζάθεον χλωρόν hin. montanha sagrada coberta de vegetação 2 amarelo; amarelado (mel, areia) 3 verde-claro 4 pálido; verde de medo: χλωροτέρα... ποίας ἔμμι safo estou mais pálido do que a grama 5 bilioso: χρῶμα χλωρόν hipócr. tez biliosa 6 que faz empalidecer; que faz amarelar (medo) 7 verde (op. a seco ou maduro): τοῦ σίτου ἔτι χλωροῦ ὄντος tuc. enquanto que o trigo estava ainda verde, χλωρὰ ξύλα artt. madeira verde 8 novo em folha; recente; fresco: τυρὸς χλωρός ar. queijo fresco 9 forte; vigoroso·(sangue, joelho).</p></section></article>\n<article id=\"entry-dgp-43699\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χλωρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 436 na letra χ · nº geral 43699</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cor verde: χλ. ὕλης plut. o verde da selva 2 cor pálida; palidez 3 cor amarela: χλ. χρυσίου sept. o amarelo do ouro 4 valor; ânimo; vigor. 〈χλωρός〉</p></section></article>\n<article id=\"entry-dgp-43700\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χνοάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 437 na letra χ · nº geral 43700</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter os primeiros pelos de barba. 〈χνόος〉</p></section></article>\n";
